const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const dcPoint = ee.Geometry.Point([-77.0369, 38.9072]); // A central point in Washington D.C.
  const startDate = '2018-01-01';
  const endDate = '2019-01-01'; // End date is exclusive for filterDate

  // 2. Data Acquisition & Check
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate)
    .filterBounds(dcPoint)
    .select('precipitation'); // Select the precipitation band

  const collectionSize = await chirps.size().getInfo();
  if (collectionSize === 0) {
    console.log("No CHIRPS images found for Washington D.C. in 2018.");
    console.log("C1");
    return;
  }
  console.log(`2018 CHIRPS images: ${collectionSize}`);

  // 3. Processing: Calculate total precipitation for the year
  // Sum all daily precipitation images into a single annual total image.
  const annualPrecipImage = chirps.sum();

  // Reduce the annual total image to get the precipitation value for the DC point.
  // Use a slightly larger scale for point reduction to ensure some pixels are hit.
  const precipStats = await annualPrecipImage.reduceRegion({
    reducer: ee.Reducer.mean().setOutputs(['precipitation']), // Mean for a single point is its value
    geometry: dcPoint,
    scale: 5000, // A coarser scale is good for efficiency and point sampling
    maxPixels: 1e9
  }).getInfo();

  // Also count the number of valid pixels to check for C2, although for a point and CHIRPS, it's less likely to be 0
  const pixelCount = await annualPrecipImage.reduceRegion({
    reducer: ee.Reducer.count().setOutputs(['precipitation']),
    geometry: dcPoint,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const validPixels = pixelCount ? pixelCount.precipitation : 0;
  if (validPixels === 0) {
    console.log("No valid pixels found for precipitation after processing.");
    console.log("C2");
    return;
  }

  // 4. Calculation & Validation
  const totalPrecipMM = precipStats ? precipStats.precipitation : null;

  if (totalPrecipMM === null || isNaN(totalPrecipMM)) {
    console.log("Calculation failed: Precipitation value is null or NaN.");
    console.log("C3");
    return;
  }

  // Convert millimeters to inches (1 inch = 25.4 mm)
  const totalPrecipInches = totalPrecipMM / 25.4;

  console.log(`Total precipitation in 2018 for Washington D.C.: ${totalPrecipInches.toFixed(2)} inches`);
  console.log(`Valid pixels: ${validPixels}`);

  // 5. Final Answer
  if (totalPrecipInches >= 50) {
    console.log("A"); // Yes, it experienced at least 50 inches of rainfall.
  } else {
    console.log("B"); // No, it did not experience at least 50 inches of rainfall.
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
